package team.rustcraft.building;
import org.junit.jupiter.api.Test;import team.rustcraft.api.building.*;import team.rustcraft.api.death.WorldPosition;import team.rustcraft.api.event.SimpleEventBus;import team.rustcraft.api.player.PlayerId;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class BuildingValidationTest { PlayerId a=new PlayerId(UUID.randomUUID()), b=new PlayerId(UUID.randomUUID()); InMemoryBuildingService svc=new InMemoryBuildingService(new SimpleEventBus());
 @Test void foundationRequiresAirAndSupport(){ var v=new BuildingPlacementValidator(svc,BuildingConfig.defaults()); var origin=new WorldPosition("overworld",0,64,0); var ok=v.validateFoundation(a,origin,new BuildingPlacementValidator.WorldAccess(){public boolean isAir(WorldPosition p){return true;} public boolean isSolid(WorldPosition p){return p.y()==63;}}); assertTrue(ok.valid()); var bad=v.validateFoundation(a,origin,new BuildingPlacementValidator.WorldAccess(){public boolean isAir(WorldPosition p){return false;} public boolean isSolid(WorldPosition p){return true;}}); assertEquals(BuildingPlacementValidator.Reason.OCCUPIED,bad.reason()); }
 @Test void tcPrivilegeRequiresAuthorization(){ svc.placeToolCupboard(new ToolCupboardId("tc"),a,new WorldPosition("overworld",0,64,0),true); var v=new BuildingPlacementValidator(svc,new BuildingConfig(true,20)); assertTrue(v.hasPrivilege(a,new WorldPosition("overworld",1,64,1))); assertFalse(v.hasPrivilege(b,new WorldPosition("overworld",1,64,1))); assertTrue(v.hasPrivilege(b,new WorldPosition("overworld",30,64,1))); }
 @Test void authorizationAddsPlayer(){ var id=new ToolCupboardId("tc"); svc.placeToolCupboard(id,a,new WorldPosition("overworld",0,64,0),true); svc.authorizePlayer(id,b); assertTrue(svc.findToolCupboard(id).orElseThrow().isPlayerAuthorized(b)); }
 @Test void upgradesOnlyFromTwigAndConsumeResources(){ var building=svc.createBuilding(new BuildingId("b"),a); var block=svc.addBlock(new BuildingBlockId("bb"),building.id(),BuildingBlockType.FOUNDATION,BuildingGrade.TWIG,10,new WorldPosition("overworld",0,64,0)); var v=new BuildingPlacementValidator(svc,BuildingConfig.defaults()); var up=new BuildingUpgradeService(svc,v,(f,t)->Map.of("wood",100)); var r=up.validateAndConsume(a,block.id(),BuildingGrade.WOOD,(p,c)->c.get("wood")==100); assertTrue(r.valid()); assertFalse(up.validateAndConsume(a,block.id(),BuildingGrade.TWIG,(p,c)->true).valid()); }
}
